abc_angle = {"A": 70, "B": 50}
abc_angle["C"] = 180 - abc_angle["A"] - abc_angle["B"]
abc_side = {frozenset("AB"): 6}
corr = dict(zip("PQR", "ABC"))           # vertex order of the congruence
angle = {v: abc_angle[corr[v]] for v in "PQR"}
side = {frozenset(s): abc_side.get(frozenset(corr[c] for c in s)) for s in ("PQ", "QR", "RP")}
claims = {"A": (("QR", 6), ("R", 60)), "B": (("QR", 6), ("Q", 60)),
          "C": (("QP", 6), ("P", 60)), "D": (("QP", 6), ("R", 60))}
def holds(c):
    (s, l), (a, d) = c
    return side[frozenset(s)] == l and angle[a] == d
opts = {k: holds(c) for k, c in claims.items()}
result = True
match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

