from math import gcd
opts = {"A": (1, 2, 4), "B": (3, 4, 8), "C": (4, 3, 2), "D": (1, 3, 4)}
def simp(t):
    g = 0
    for v in t: g = gcd(g, v)
    return tuple(v // g for v in t)
