from fractions import Fraction as F
base = {"a": F(480), "b": F(3, 10), "c": F(5), "d": F(500), "e": F(190), "f": F(9), "g": F(27), "h": F(16, 10)}
def val(v):
    return (v["a"] / v["b"] * v["c"] + v["d"]) / (v["e"] + v["f"] * v["g"] / v["h"])
def swap(x, y):
    inv = {v: k for k, v in base.items()}
    v = dict(base)
    v[inv[x]], v[inv[y]] = y, x
    return val(v)
pairs = {"A": (F(5), F(9)), "B": (F(3, 10), F(16, 10)), "C": (F(27), F(480)), "D": (F(500), F(190))}
opts = {k: swap(*p) for k, p in pairs.items()}
result = F(2)

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

